// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Milesinu {
    function owner() external view returns (address);
    function renounceOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The contract is already deployed at TARGET
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address currentOwner = Milesinu(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Impersonate the owner and renounce ownership
        vm.prank(currentOwner);
        Milesinu(TARGET).renounceOwnership();

        // Verify the owner is now address(0)
        address newOwner = Milesinu(TARGET).owner();
        console.log("New owner:", newOwner);
        assertEq(newOwner, address(0), "Owner should be zero address");
        assertEq(Milesinu(TARGET).owner(), address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
